const { spawnSync } = require("child_process");
const fs = require("fs");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const home = fs.mkdtempSync("/tmp/home-");
const cwd = fs.mkdtempSync("/tmp/proj-");
const env = { ...process.env, HOME: home, XDG_CONFIG_HOME: home + "/.config", DO_NOT_TRACK: "1", NO_COLOR: "1", FORCE_COLOR: "0" };
delete env.WRANGLER_SEND_METRICS;
const r = spawnSync(process.execPath, ["/w/node_modules/wrangler/bin/wrangler.js", "telemetry", "status"], { cwd, env, encoding: "utf8", timeout: 80000 });
const out = (r.stdout || "") + (r.stderr || "");
const m = out.match(/Status: (Enabled|Disabled)[^\n]*/);
if (!m) broken("no Status line from wrangler telemetry status (exit " + r.status + "): " + out.slice(0, 500));
if (m[1] === "Enabled") symptom("wrangler telemetry status reports Enabled with DO_NOT_TRACK=1");
console.log("OK: " + m[0]);

